import{n as s$1,s as y,t as r}from"./chunk-ALRE-57A.js";import{Dt as Qt,Jr as vy,Sn as cc,Zt as W_}from"./chunk-CvDK5P-X.js";import{ct as vc,ht as t,w as R1}from"./main-RDXNK37Y.js";import"./chunk-DY2lZFm2.js";import{t as Ii}from"./chunk-Cz9MSHse.js";var k=y(vc());var s={title:`Change detection`,mdFile:`./index.md`,order:2,category:t};var h=[];var g={};var F=`<p class="ngde">The ng-select component implements <code class="ngde">OnPush</code> change detection, which means the dirty checking checks for immutable data types. That means if you do object mutations like:</p><pre class="shiki shiki-themes github-light ayu-dark" style="background-color:#fff;--shiki-dark-bg:#0b0e14;color:#24292e;--shiki-dark:#bfbdb6" tabindex="0"><code class="language-typescript"><span class="line"><span style="color:#005CC5;--shiki-dark:#39BAE6;font-style:inherit;--shiki-dark-font-style:italic" class="ngde">this</span><span style="color:#24292E;--shiki-dark:#F29668" class="ngde">.</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde">items</span><span style="color:#24292E;--shiki-dark:#F29668" class="ngde">.</span><span style="color:#6F42C1;--shiki-dark:#FFB454" class="ngde">push</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde">({ id</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">:</span><span style="color:#005CC5;--shiki-dark:#D2A6FF" class="ngde"> 1</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">,</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> name</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">:</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> 'New item'</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> })</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">;</span></span></code></pre><p class="ngde">the component will not detect a change. Instead you need to do:</p><pre class="shiki shiki-themes github-light ayu-dark" style="background-color:#fff;--shiki-dark-bg:#0b0e14;color:#24292e;--shiki-dark:#bfbdb6" tabindex="0"><code class="language-typescript"><span class="line"><span style="color:#005CC5;--shiki-dark:#39BAE6;font-style:inherit;--shiki-dark-font-style:italic" class="ngde">this</span><span style="color:#24292E;--shiki-dark:#F29668" class="ngde">.</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde">items </span><span style="color:#D73A49;--shiki-dark:#F29668" class="ngde">=</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> [</span><span style="color:#D73A49;--shiki-dark:#F29668" class="ngde">...</span><span style="color:#005CC5;--shiki-dark:#39BAE6;font-style:inherit;--shiki-dark-font-style:italic" class="ngde">this</span><span style="color:#24292E;--shiki-dark:#F29668" class="ngde">.</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde">items</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">,</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> { id</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">:</span><span style="color:#005CC5;--shiki-dark:#D2A6FF" class="ngde"> 1</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">,</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> name</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">:</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> 'New item'</span><span style="color:#24292E;--shiki-dark:#BFBDB6" class="ngde"> }]</span><span style="color:#24292E;--shiki-dark:#BFBDB6B3" class="ngde">;</span></span></code></pre><p class="ngde">This will cause the component to detect the change and update. Some might have concerns that this is a pricey operation; however, it is much more performant than running <code class="ngde">ngDoCheck</code> and constantly diffing the array.</p><h2 id="zoneless-change-detection" href="getting-started/change-detection" headinglink="true" class="ngde">Zoneless change detection<ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="zoneless-change-detection"></ng-doc-heading-anchor></h2><p class="ngde"><code class="ngde">@ng-select/ng-select</code> and <code class="ngde">@ng-select/ng-option-highlight</code> fully support <a href="https://angular.dev/guide/zoneless" class="ngde">zoneless change detection</a> \u2014 the default for new Angular apps since v21. No setup is required: the libraries do not depend on <code class="ngde">zone.js</code> (it is not in their dependency graphs) and work identically whether your app is zoneless or still uses <code class="ngde">zone.js</code>. Both modes are covered by the unit-test suite in CI, and this docs site runs zoneless.</p>`;var D=(()=>{class e extends R1{constructor(){super(),this.pageType=`guide`,this.pageContent=F,this.editSourceFileUrl=`https://github.com/ng-select/ng-select/edit/master/src/demo/app/docs/getting-started/change-detection/index.md?message=docs(): describe your changes here...`,this.viewSourceFileUrl=`https://github.com/ng-select/ng-select/blob/master/src/demo/app/docs/getting-started/change-detection/index.md`,this.page=s,this.demoAssets=g}static{this.ɵfac=function(n){return new(n||e)}}static{this.ɵcmp=Qt({type:e,selectors:[[`ng-doc-page-r7a0li2c`]],features:[W_([{provide:R1,useExisting:e},h,s.providers??[]]),vy],decls:1,vars:0,template:function(n,C){n&1&&cc(0,`ng-doc-page`)},dependencies:[Ii],encapsulation:2})}}return e})();var z=[s$1(r({},(0,k.isRoute)(s.route)?s.route:{}),{path:``,component:D,title:`Change detection`})];export{D as PageComponent,z as default};